/**
 * Kill all the apps that have been running for too long.
 */
public void deleteLongRunningApplications() {
    List<NamespaceAndName> expiredApplications = runningApplications.entrySet().stream().filter(t -> t.getValue().exceedMaxRunningTime()).map(t -> t.getKey()).collect(Collectors.toList());
    for (NamespaceAndName app : expiredApplications) {
        RunningAppInfo runningAppInfo = runningApplications.remove(app);
        if (runningAppInfo != null) {
            logger.info("Killing application {}/{} due to running too long ({} milliseconds)", app.getNamespace(), app.getName(), System.currentTimeMillis() - runningAppInfo.getCreationTimeMillis());
            try {
                killApplication(app.getNamespace(), app.getName());
            } catch (Throwable ex) {
                logger.warn(String.format("Failed to kill application %s/%s", app.getNamespace(), app.getName()), ex);
            }
        }
    }
}
